SOURCE = 'def skachat(file_id, cel, proverka=None):\n    """Качает файл в .part, проверяет и только потом ставит на место."""\n    chastichno = cel + ".part"\n    posledn = "файл не найден ни одним ботом"\n    for tok in tokeny():\n        dorozhka = put_v_telegram(tok, file_id)\n        if not dorozhka:\n            continue\n        adres = "https://api.telegram.org/file/bot%s/%s" % (tok, dorozhka)\n        try:\n            with urllib.request.urlopen(adres, timeout=TAYMAUT_SKACHIVANIYA) as r, \\\n                    open(chastichno, "wb") as f:\n                shutil.copyfileobj(r, f)\n        except Exception as e:\n            posledn = "этап скачивания: %r" % e\n            continue\n        if not (proverka or vnutri_mp4)(chastichno):\n            posledn = "скачалось не то, что ждали"\n            try:\n                os.remove(chastichno)\n            except Exception:\n                pass\n            continue\n        try:\n            os.replace(chastichno, cel)\n        except Exception as e:\n            posledn = "не поставить на место: %r" % e\n            continue\n        if cel.lower().endswith(".mp4"):\n            zastavka(cel)\n        return True, "%d байт" % os.path.getsize(cel)\n    try:\n        if os.path.exists(chastichno):\n            os.remove(chastichno)\n    except Exception:\n        pass\n    return False, posledn\n\ndef _spisok_fid(znachenie, predel):\n    try:\n        dannye = json.loads(znachenie or "[]")\n    except Exception:\n        return []\n    out = []\n    for el in dannye if isinstance(dannye, list) else []:\n        fid = el.get("file_id") if isinstance(el, dict) else el\n        if fid:\n            out.append(str(fid))\n    return out[:predel]\n\ndef mashiny():\n    """Номер машины -> {\'video\': [file_id...], \'foto\': [file_id...]}."""\n    out = {}\n    try:\n        con = sqlite3.connect("file:%s?mode=ro" % BD, uri=True, timeout=20)\n        cur = con.cursor()\n        cur.execute("PRAGMA table_info(cars)")\n        kol = [r[1] for r in cur.fetchall()]\n        pole = next((k for k in ("auto_number", "code", "number") if k in kol), None)\n        if not pole or "videos" not in kol:\n            con.close()\n            return out\n        polya = [pole, "videos"] + (["photos"] if "photos" in kol else [])\n        cur.execute("SELECT %s FROM cars" % ", ".join(polya))\n        for r in cur.fetchall():\n            znach = dict(zip(polya, r))\n            nom = str(znach.get(pole) or "").upper().strip()\n            if not nom:\n                continue\n            out[nom] = {\n                "video": _spisok_fid(znach.get("videos"), PREDEL_ROLIKOV),\n                "foto": _spisok_fid(znach.get("photos"), PREDEL_FOTO),\n            }\n        con.close()\n    except Exception as e:\n        log("база недоступна: %r" % e)\n    return out\n\ndef prohod():\n    """Один проход сверки. Возвращает короткий итог строкой."""\n    if os.path.exists(STOP):\n        return "остановлен файлом video_sinhron_stop.txt"\n    if not os.path.isdir(PUB):\n        return "нет папки %s" % PUB\n\n    vse = mashiny()\n    if not vse:\n        return "в базе не прочиталось ни одной машины — проход отменён"\n\n    pamyat = pamyat_chitat()\n    mertvye = pamyat.get("_ne_kachaetsya") or {}\n    skachano = udaleno = 0\n    izmenilos = []\n    ostatok = PREDEL_ZA_PROHOD\n    ostatok_foto = PREDEL_FOTO_ZA_PROHOD\n    skachano_foto = udaleno_foto = 0\n\n    for nom in sorted(vse):\n        fid_spisok = vse[nom]["video"]\n        fid_foto = vse[nom]["foto"]\n        nuzhno = {}\n        for i, fid in enumerate(fid_spisok, 1):\n            nuzhno[imya_rolika(nom, i)] = fid\n        bylo = svoi_fayly(nom)\n        znal = pamyat.get(nom) or {}\n        sboi_mashiny = []\n\n        # лишнее с диска\n        for imya in bylo:\n            if imya not in nuzhno:\n                udaleno += ubrat(os.path.join(PUB, imya))\n                izmenilos.append(nom)\n\n        # недостающее и подменённое\n        for imya, fid in nuzhno.items():\n            cel = os.path.join(PUB, imya)\n            na_meste = os.path.exists(cel) and znal.get(imya) == fid\n            if na_meste:\n                continue\n            if ostatok <= 0:\n                continue\n            kogda = mertvye.get(fid)\n            if kogda and time.time() - kogda < POVTOR_MERTVYH:\n                continue   # Telegram уже отказал: не дёргаем его без конца\n            ostatok -= 1\n            zasechka = time.time()\n            horosho, chto = skachat(fid, cel)\n            chto = "%s, %.0f сек" % (chto, time.time() - zasechka)\n            if horosho:\n                skachano += 1\n                mertvye.pop(fid, None)\n                znal[imya] = fid\n                izmenilos.append(nom)\n                log("car_id=%s operation=video_download source=telegram:%s "\n                    "destination=%s result=SUCCESS (%s)" % (nom, fid[:24], cel, chto))\n            else:\n                mertvye[fid] = time.time()\n                sboi_mashiny.append("%s: %s (пробую снова через 6 часов)" % (imya, chto))\n                log("car_id=%s operation=video_download source=telegram:%s "\n                    "destination=%s result=ERROR (%s)" % (nom, fid[:24], cel, chto))\n\n        # ── фотографии: те же правила, что и для роликов\n        nuzhno_f = {}\n        for i, fid in enumerate(fid_foto, 1):\n            nuzhno_f[imya_foto(i)] = fid\n        bylo_f = svoi_foto(nom)\n        znal_f = pamyat.get("foto:" + nom) or {}\n        menyalis_foto = False\n\n        for imya in bylo_f:\n            if imya not in nuzhno_f:\n                if ubrat(os.path.join(foto_papka(nom), imya)):\n                    udaleno_foto += 1\n                    menyalis_foto = True\n\n        if nuzhno_f:\n            try:\n                os.makedirs(foto_papka(nom), exist_ok=True)\n            except Exception as e:\n                sboi_mashiny.append("не создать папку фото: %r" % e)\n\n        for imya in sorted(nuzhno_f):\n            fid = nuzhno_f[imya]\n            cel = os.path.join(foto_papka(nom), imya)\n            if os.path.exists(cel) and znal_f.get(imya) == fid:\n                continue\n            if ostatok_foto <= 0:\n                continue\n            kogda = mertvye.get(fid)\n            if kogda and time.time() - kogda < POVTOR_MERTVYH:\n                continue\n            ostatok_foto -= 1\n            horosho, chto = skachat(fid, cel, vnutri_jpeg)\n            if horosho:\n                skachano_foto += 1\n                menyalis_foto = True\n                mertvye.pop(fid, None)\n                znal_f[imya] = fid\n            else:\n                mertvye[fid] = time.time()\n                sboi_mashiny.append("фото %s: %s (пробую снова через 6 часов)"\n                                    % (imya, chto))\n\n        znal_f = {k: v for k, v in znal_f.items() if k in nuzhno_f}\n        if znal_f:\n            pamyat["foto:" + nom] = znal_f\n        else:\n            pamyat.pop("foto:" + nom, None)\n\n        if menyalis_foto:\n            chistit_kesh(nom)\n            izmenilos.append(nom)\n            log("car_id=%s operation=foto_sync crm_foto_count=%d "\n                "site_foto_count_before=%d site_foto_count_after=%d"\n                % (nom, len(fid_foto), len(bylo_f), len(svoi_foto(nom))))\n\n        # память о том, что где лежит\n        znal = {k: v for k, v in znal.items() if k in nuzhno}\n        if znal:\n            pamyat[nom] = znal\n        else:\n            pamyat.pop(nom, None)\n\n        if nom in izmenilos:\n            stalo = svoi_fayly(nom)\n            log("car_id=%s operation=video_sync crm_video_count=%d "\n                "site_video_count_before=%d site_video_count_after=%d state_path=%s"\n                % (nom, len(fid_spisok), len(bylo), len(stalo), PAMYAT))\n        for s in sboi_mashiny:\n            log("car_id=%s operation=video_sync ERROR %s" % (nom, s))\n\n    pamyat["_ne_kachaetsya"] = mertvye\n    if izmenilos:\n        pamyat_pisat(pamyat)\n        horosho, oshibka = peresobrat()\n        log("operation=site_rebuild cars=%s peresborka=%s (%s)"\n            % (",".join(sorted(set(izmenilos))), "SUCCESS" if horosho else "ERROR",\n               oshibka or "?"))\n        itog = ("роликов скачано %d, убрано %d · фото скачано %d, убрано %d"\n                % (skachano, udaleno, skachano_foto, udaleno_foto))\n        if not horosho:\n            return itog + " · пересборка страниц не прошла: %s" % oshibka\n        return itog + " · страницы пересобраны"\n    if mertvye:\n        pamyat_pisat(pamyat)\n    return "всё совпадает, менять нечего"\n\ndef _cikl():\n    log("сторож запущен (%s)" % "UA-V120")\n    while True:\n        try:\n            itog = prohod()\n            if itog and "менять нечего" not in itog:\n                log(itog)\n        except Exception:\n            log("сбой прохода:\\n" + traceback.format_exc())\n        time.sleep(SHAG)\n'
